import { render, screen } from '@testing-library/react';
import React from 'react';
import { describe, expect, it } from 'vitest';

import { MessageBox } from '../../components/ui/message-box';

describe('MessageBox skeleton width', () => {
    // A runtime-built `w-[300px]` class is never generated by Tailwind, so lengths must be inline.
    it.each([
        [300, '300px'],
        ['240px', '240px'],
        ['50%', '50%'],
    ])('applies %p as an inline width', (width, expected) => {
        render(<MessageBox isLoading loadingType="skeleton" width={width} />);
        const box = screen.getByRole('status');
        expect(box.style.width).toBe(expected);
        expect(box.className).not.toMatch(/w-\[/);
    });

    it('treats a non-length string as a Tailwind class', () => {
        render(<MessageBox isLoading loadingType="skeleton" width="w-96" />);
        const box = screen.getByRole('status');
        expect(box.className).toContain('w-96');
        expect(box.style.width).toBe('');
    });
});

describe('MessageBox message', () => {
    const box = () => screen.getByRole('status');
    const icon = () => box().querySelector('svg');

    it('shows a string as an info message by default', () => {
        render(<MessageBox message="Nothing here yet" />);
        expect(box()).toHaveTextContent('Nothing here yet');
        expect(box()).toHaveAttribute('data-type', 'info');
        expect(icon()).toHaveClass('text-info');
        expect(box().className).toContain('cursor-default');
    });

    it.each([
        ['error', 'text-destructive'],
        ['warning', 'text-warning'],
        ['success', 'text-success'],
        ['help', 'text-primary'],
        ['loginRequired', 'text-muted-foreground'],
        ['disconnected', 'text-muted-foreground'],
        ['loading', 'text-primary'],
    ] as const)('draws the %s icon in %s', (messageType, tone) => {
        render(<MessageBox message="msg" messageType={messageType} />);
        expect(box()).toHaveAttribute('data-type', messageType);
        expect(icon()).toHaveClass(tone);
        // The icon is decoration: the message is what a screen reader announces
        expect(icon()).toHaveAttribute('aria-hidden', 'true');
    });

    it('shows an Error as an error whatever type was asked for', () => {
        render(<MessageBox message={new Error('Boom')} messageType="success" />);
        expect(box()).toHaveTextContent('Boom');
        expect(box()).toHaveAttribute('data-type', 'error');
        expect(icon()).toHaveClass('text-destructive');
        expect(box().className).toContain('cursor-not-allowed');
    });

    it('falls back to the error name when its message is empty', () => {
        const error = new TypeError('');
        render(<MessageBox message={error} />);
        expect(box()).toHaveTextContent('TypeError');
    });

    it('shows a plain object as formatted JSON', () => {
        render(<MessageBox message={{ code: 42, ok: false }} />);
        const pre = box().querySelector('pre');
        expect(pre?.textContent).toBe(JSON.stringify({ code: 42, ok: false }, null, 2));
        // An object is data, not a failure: the requested type stands
        expect(box()).toHaveAttribute('data-type', 'info');
    });

    it('renders a React node as given', () => {
        render(<MessageBox message={<a href="/retry">Try again</a>} messageType="warning" />);
        expect(screen.getByRole('link', { name: 'Try again' })).toBeInTheDocument();
        expect(box()).toHaveAttribute('data-type', 'warning');
    });

    it('says so when there is no message at all', () => {
        render(<MessageBox />);
        expect(box()).toHaveTextContent('An error has occurred.');
    });

    it('falls back to the info icon for a type it does not know', () => {
        render(<MessageBox message="msg" messageType={'mystery' as never} />);
        expect(icon()).toHaveClass('text-info');
    });
});

describe('MessageBox loading', () => {
    it('shows the spinner and no message', () => {
        render(<MessageBox isLoading message="ignored" />);
        // One status: the spinner. The message and its icon are not rendered while loading
        expect(screen.getByRole('status', { name: 'Loading' })).toBeInTheDocument();
        expect(screen.queryByText('ignored')).toBeNull();
    });

    it('shows the skeleton placeholders when asked', () => {
        render(<MessageBox isLoading loadingType="skeleton" />);
        const skeleton = screen.getByRole('status');
        expect(skeleton).toHaveAttribute('aria-live', 'polite');
        expect(skeleton.querySelectorAll('.animate-pulse').length).toBeGreaterThan(5);
    });
});
